    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        paths.sort();

        if paths.is_empty() {
            return ExitCode::Success;
        }

        // Leave some headroom below the platform's maximum argument length to
        // account for the executable path, fixed arguments and the environment.
        let max_arg_length = max_command_arg_length();

        let mut results = Vec::new();
        let mut paths = paths.into_iter().peekable();

        while paths.peek().is_some() {
            let mut cmd = Command::new(self.args[0].generate("", None));
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            let mut cmd_len = self.args[0].generate("", None).len();
            let mut has_path = false;

            for arg in &self.args[1..] {
                if arg.has_tokens() {
                    // A single `Tokens` is expected, so we can directly
                    // consume as many paths as fit within `max_arg_length`.
                    let mut added_any = false;
                    while let Some(path) = paths.peek() {
                        let generated =
                            arg.generate(strip_current_dir(path), self.path_separator.as_deref());
                        let generated_len = generated.len() + 1;

                        if added_any && cmd_len + generated_len > max_arg_length {
                            break;
                        }

                        cmd_len += generated_len;
                        cmd.arg(generated);
                        has_path = true;
                        added_any = true;

                        paths.next();
                    }
                } else {
                    let generated = arg.generate("", None);
                    cmd_len += generated.len() + 1;
                    cmd.arg(generated);
                }
            }

            if has_path {
                results.push(execute_command(cmd, &Mutex::new(()), buffer_output));
            }
        }

        merge_exitcodes(results)
    }
}

/// Determine the maximum length (in bytes) that should be used for a batch of
/// command-line arguments, leaving some headroom below the platform's actual
/// maximum to account for the executable path and the environment.
fn max_command_arg_length() -> usize {
    #[cfg(all(unix, not(target_os = "redox")))]
    fn platform_arg_max() -> usize {
        let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
        if arg_max <= 0 {
            // Fall back to a conservative default (POSIX minimum is 4096, but
            // most systems support much more).
            128 * 1024
        } else {
            arg_max as usize
        }
    }

    #[cfg(not(all(unix, not(target_os = "redox"))))]
    fn platform_arg_max() -> usize {
        // Windows' CreateProcess has a command-line length limit of ~32767
        // characters. Other platforms without a known limit use a
        // conservative default as well.
        32 * 1024
    }

    // Reserve half of the available space for the environment and other
    // fixed overhead, similar to what GNU xargs does.
    platform_arg_max() / 2
}
